<template>
  <div class="page-shell events-page">
    <div v-loading="loading" class="event-table surface">
      <div class="filters"><div class="status-filters" role="group" aria-label="按巡检状态筛选"><button v-for="option in filterOptions" :key="option.value" type="button" :aria-pressed="filter === option.value" :class="{active:filter === option.value}" @click="filter = option.value; load()">{{ option.label }}</button></div><span>共 {{ total }} 条</span></div>
      <div class="table-head"><span>巡检 / 烟田</span><span>状态</span><span>设备</span><span>现场数据</span><span>开始时间</span><span></span></div>
      <router-link v-for="item in items" :key="item.inspection_id" :to="`/platform/inspections/${item.inspection_id}`" class="event-row">
        <div class="event-name"><div><b>{{ item.name }}</b><small>{{ item.field_name || '未关联烟田' }} · {{ item.inspection_id.slice(0, 8) }}</small></div></div>
        <span :class="['status', item.status.toLowerCase()]"><i></i>{{ statusName(item.status) }}</span>
        <span class="mono cell">{{ item.device_id }}</span>
        <div class="data-count"><span><b>{{ item.sample_count }}</b> 点位</span><span><b>{{ item.image_count }}</b> 图片</span><span><b>{{ item.target_count }}</b> 目标</span></div>
        <span class="cell">{{ formatDate(item.started_at || item.created_at) }}</span><span class="arrow">↗</span>
      </router-link>
      <div v-if="!items.length && !loading" class="empty"><div class="empty-mark"><el-icon><Tickets /></el-icon></div><h3>还没有巡检记录</h3><p>在微信小程序选择烟田与设备，完成设备检查并确认开始巡检后，记录会显示在这里。</p></div>
    </div>

  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { platformApi } from '@/api/platform'
import type { InspectionEventItem } from '@/types'
const loading=ref(true), filter=ref(''), total=ref(0); const items=ref<InspectionEventItem[]>([])
const filterOptions=[{value:'',label:'全部'},{value:'RUNNING',label:'进行中'},{value:'COMPLETED',label:'已完成'},{value:'FAILED',label:'异常'}]
async function load(){loading.value=true;try{const d=await platformApi.events({status:filter.value||undefined,page_size:50});items.value=d.items;total.value=d.total}finally{loading.value=false}}
function statusName(v:string){return ({CREATED:'待开始',RUNNING:'进行中',SYNCING:'同步中',COMPLETED:'已完成',FAILED:'异常',CANCELLED:'已取消'} as Record<string,string>)[v]||v}
function formatDate(v?:string|null){return v?new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'}
onMounted(load)
</script>

